def find_golomb_ruler(n=7, fixed={0:0, 1:2}, max_length=100):
    # marks is list of positions
    marks = [None]*n
    for idx,val in fixed.items():
        marks[idx]=val
    used_distances = set()
    # precompute used distances from fixed marks
    for i in range(n):
        if marks[i] is not None:
            for j in range(i+1,n):
                if marks[j] is not None:
                    d = marks[j]-marks[i]
                    if d in used_distances:
                        return None # conflict in fixed assignments
                    used_distances.add(d)

    # backtracking
    def backtrack(k):
        if k==n:
            return list(marks)
        # determine lower bound for marks[k]
        if marks[k-1] is not None:
            low = marks[k-1]+1
        else:
            # find previous defined mark
            prev = k-1
            while prev>=0 and marks[prev] is None:
                prev -= 1
            low = marks[prev]+1 if prev>=0 else 0
        # upper bound
        high = max_length
        # optional: reduce high based on remaining marks? not needed for small n
        for pos in range(low, high+1):
            # check distances with already placed marks
            ok = True
            new_dists = []
            for i in range(k):
                if marks[i] is not None:
                    d = pos - marks[i]
                    if d in used_distances:
                        ok = False
                        break
                    new_dists.append(d)
            if not ok:
                continue
            # place
            marks[k] = pos
            for d in new_dists:
                used_distances.add(d)
            res = backtrack(k+1)
            if res is not None:
                return res
            # undo
            marks[k] = None
            for d in new_dists:
                used_distances.remove(d)
        return None

    # find first unset index
    start = 0
    while start<n and marks[start] is not None:
        start += 1
    return backtrack(start)

for max_len in [30,40,50,60,80,100]:
    sol = find_golomb_ruler(max_length=max_len)
    print(max_len, sol)
